package com.example

import com.example.ExamQuestionHelper.QSpec

object MusicLiveExamTheatreDramaBank2 {
    private const val T = "නූර්ති, නාඩගම් සහ සිංහල නාට්‍ය සංගීතය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("'සප්ත ස්වරයයි සප්ත ස්වරයයි' වැනි ගීත හරහා වේදිකා නාට්‍ය සංගීතය ජනප්‍රිය කළ නිර්මාණකරුවා කවුද?", "සයිමන් නවගත්තේගම සහ පිරිස", "විශ්වනාත් ලෞජි", "ජෝන් ද සිල්වා", "පිලිප්පු සිංඤෝ", "නූතන වේදිකා නාට්‍යවලදී නාට්‍යකරුවන් හා සංගීතවේදීන් නව තනු නිර්මාණය කළහ."),
        q("නාඩගම් සම්ප්‍රදාය පිළිබඳ ගැඹුරු ශාස්ත්‍රීය පර්යේෂණ කළ ප්‍රවීණ විද්වතා කවුද?", "මහාචාර්ය එදිරිවීර සරච්චන්ද්‍ර", "ආතර් සී. ක්ලාක්", "මාර්ටින් වික්‍රමසිංහ", "සෙනරත් පරණවිතාන", "සරච්චන්ද්‍රයන් සිංහල ගැමි නාටකය හා නාඩගම් කලාව පිළිබඳ විද්වත් ග්‍රන්ථ ලීවේය."),
        q("නාඩගම් ගීතයක් ආරම්භ කිරීමට පෙර මද්දලය මගින් වාදනය කරනු ලබන තාල පද කොටස හඳුන්වන්නේ කෙසේද?", "වට්ටම හෝ අඩව් පදය", "ඛ්‍යාල් අලාපය", "බටහිර පෙරවදන", "සර්ගම් ගීතය", "ගායකයා ගීතය අල්ලා ගැනීමට පෙර මද්දලයෙන් විශේෂ තාල පද කොටසක් වාදනය කෙරේ."),
        q("ශ්‍රී ලංකාවේ දකුණු පළාතේ වැලිගම හා මාතර ආශ්‍රිතව රැකගෙන ආ නාඩගම් ආර කුමක්ද?", "දකුණු සිංහල නාඩගම් ආර", "කන්ද උඩරට වන්නම් ආර", "පාර්සි නූර්ති ආර", "සබරගමු බලි ආර", "වැලිගම ගුණසිංහ ගුරුන්නාන්සේ ප්‍රමුඛ ශිල්පීන් දකුණේ නාඩගම් පරපුර රැකගත්හ."),
        q("සිංහල නූර්ති ගීතවල ජනප්‍රියතාව කෙරෙහි බලපෑ ප්‍රධාන හේතුව කුමක්ද?", "කන්කලු රාගධාරී තනු හා බුදුගුණ පදමාලා", "ඉංග්‍රීසි භාෂාවෙන් ගායනා කිරීම", "සංගීත භාණ්ඩ භාවිත නොකිරීම", "රාත්‍රී කාලයේ ප්‍රදර්ශනය නොකිරීම", "සිත් ඇදගන්නා උත්තර භාරතීය තනු සහ බෞද්ධ සාරධර්ම පද නිසා නූර්ති ජනප්‍රිය විය."),
        q("'සත්ත්ව කරුණාව පා සිරිලක පුරා' වැනි දේශාභිමානී ගී බිහිවූයේ කුමන යුගයේද?", "ජෝන් ද සිල්වාගේ නූර්ති යුගයේ", "පැරණි කෝලම් යුගයේ", "නූතන ටෙලිනාට්‍ය යුගයේ", "පෘතුගීසි පාලන යුගයේ", "ජාතික හා ආගමික පුනරුදය වෙනුවෙන් ජෝන් ද සිල්වා නූර්ති ගී රචනා කළේය."),
        q("නූර්ති නාට්‍යවලදී වාද්‍ය වෘන්දය රඟහල තුළ අසුන් ගන්නේ කවර ස්ථානයකද?", "වේදිකාව ඉදිරිපස පහළින් හෝ පසෙකින්", "ප්‍රේක්ෂකාගාරයේ පිටුපසම පේළියේ", "වේදිකාවේ වහලය මත", "නාට්‍ය ශාලාවෙන් පිටත මිදුලේ", "නූර්ති රඟහලේ වේදිකාව ඉදිරිපස වාද්‍ය මණ්ඩපයේ හාමෝනියම් තබ්ලා වාදකයෝ සිටියහ."),
        q("ග්‍රැමෆෝන් යුගයේ ජනප්‍රිය වූ 'දුල් රූ දිස්නේ' හෝ 'මනරංජන දර්ශනීය ලංකා' ගී ගැයූ ගායකයා කවුද?", "එච්. ඩබ්ලිව්. රූපසිංහ මාස්ටර්", "පිලිප්පු සිංඤෝ", "ජෝන් ද සිල්වා", "චාල්ස් ගුණසිංහ", "රූපසිංහ මාස්ටර් හින්දුස්ථානි රාග ඇසුරෙන් ග්‍රැමෆෝන් ගීත ගායනා කළේය."),
        q("ග්‍රැමෆෝන් යුගයේ ප්‍රසිද්ධ කාන්තා ගායිකාවක් වූයේ කවුද?", "රුක්මණී දේවි හෝ කෝකිල දේවී වීරතුංග", "සෝමා කාන්තා", "පද්මාවතී කුමරිය", "සුප්පා දේවිය", "රුක්මණී දේවි, කෝකිල දේවී හා ග්‍රේටා ජෙනට් ද සිල්වා ග්‍රැමෆෝන් යුගයේ ප්‍රමුඛ ගායිකාවෝ වූහ."),
        q("'මව්පිය ආදි ගරු' වැනි මුල් යුගයේ දේශීය චිත්‍රපට හා ග්‍රැමෆෝන් ගී නිර්මාණය කළ සංගීතඥයා කවුද?", "මොහොමඩ් ගවුස් මාස්ටර්", "පිලිප්පු සිංඤෝ", "විශ්වනාත් ලෞජි", "සී. දොන් බස්තියන්", "මොහොමඩ් ගවුස් මාස්ටර් ග්‍රැමෆෝන් හා මුල් චිත්‍රපට සංගීතයේ ප්‍රබල පුරෝගාමියෙකි."),
        q("නාඩගමක ප්‍රධාන පෙළේ රජ චරිත වේදිකාවට පැමිණීමේදී භාවිත කරන සාම්ප්‍රදායික පද්‍ය රීතිය කුමක්ද?", "සිංහරාජ හෝ දීර්ඝ විරිදු කවි", "දෙපද හයිකු කවි", "නිසඳැස් වචන", "වේගවත් රැප් ඛණ්ඩ", "රජෙකුගේ තේජස පෙන්වීමට ගාම්භීර ලයකින් යුත් ඉන්නිස හා කවි ගායනා කෙරේ."),
        q("'මනමේ' නාට්‍යයේ සම්පූර්ණ වේදිකා රංගනයේදී වැඩිම කොටසක් පදනම් වන්නේ කුමන කලාංගය මතද?", "ගායනය, වාදනය හා ශෛලිගත නර්තනය", "නිහඬ අභිනය පමණක්", "යාන්ත්‍රික ප්‍රයෝග පමණක්", "දීර්ඝ ගද්‍ය දේශන පමණක්", "මනමේ නාට්‍යය ගායනය, වාදනය සහ ශෛලිගත නැටුම් එක්කළ සම්පූර්ණ සංගීත නාට්‍යයකි."),
        q("මනමේ කුමාරයා දිසාපාමොක් ඇදුරුතුමාගෙන් සමුගෙන ගමන් අරඹන අවස්ථාවේ ගැයෙන ගීතය කුමක්ද?", "ප්‍රේමයෙන් මන රංජිත වේ", "ලප නොමවන් සඳ සේ", "ගල් ලෙන බිඳලා", "දන්නෝ බුදුන්ගේ", "මනමේ කුමරු හා කුමරිය එක්ව ගමන් කරමින් ප්‍රේමයෙන් මන රංජිත වේ ගීතය ගයති."),
        q("'බණ්ඩාර නායක' හෝ 'මහසාර' නාට්‍යවල සංගීත නිර්මාණයේදී සරච්චන්ද්‍රයන්ගේ අරමුණ වූයේ කුමක්ද?", "දේශීය ගැමි කවි හා සම්භාව්‍ය නාද එක්කිරීම", "බටහිර පොප් ගීත හඳුන්වා දීම", "සංගීතය සම්පූර්ණයෙන් ඉවත් කිරීම", "හින්දි චිත්‍රපට ගීත අනුකරණය කිරීම", "දේශීය සම්ප්‍රදාය පෝෂණය කරමින් නව සිංහල නාට්‍ය භාෂාවක් ගොඩනැගීම ඔහුගේ අරමුණ විය."),
        q("නාඩගම් පොතේගුරුට ගායනයේදී සහාය වීම සඳහා වේදිකාවේ සිටින කණ්ඩායම හඳුන්වන්නේ කෙසේද?", "අත්වැල් ගායක කණ්ඩායම", "තූර්ය වාදක කණ්ඩායම", "වෙස්මුහුණු කැටයම් පිරිස", "තිර අදින කණ්ඩායම", "පොතේගුරු ගයන පද පුනරුච්චාරණය කරමින් අත්වැල් ගායකයෝ ගීතයට සහාය වෙති."),
        q("පැරණි සිංහල නූර්ති නාට්‍ය රඟදැක්වීමේදී පිරිමින් විසින්ම කාන්තා චරිත රඟපෑමට වඩා කුමන වෙනසක් සිදුවීද?", "කාන්තාවන් වේදිකාවට ප්‍රවේශ වීම", "ළමුන් පමණක් රඟපෑම", "රූකඩ මගින් රඟදැක්වීම", "වෙස්මුහුණු පමණක් පැළඳීම", "නාඩගමට සාපේක්ෂව නූර්ති වේදිකාවට ස්ත්‍රී නිළියන් ක්‍රමයෙන් එක්වීම සිදුවිය."),
        q("නූර්ති නාට්‍ය කලාවේ මුල් කාලයේ නළු නිළියන් තම හඬ ප්‍රේක්ෂකාගාරය පුරා පැතිරවීමට යොදාගත් ක්‍රමය කුමක්ද?", "උච්ච ස්වරයෙන් ස්වාභාවිකව හඬ නගා ගැයීම", "රැහැන් රහිත මයික්‍රොෆෝන පැළඳීම", "පටිගත කළ හඬපට වාදනය කිරීම", "පිටුපසින් වෙනත් අයෙකු කතා කිරීම", "මුල් යුගයේ විදුලි ශබ්ද විකාශන නොතිබූ බැවින් ගායකයන්ට ප්‍රබල කටහඬක් තිබිය යුතු විය."),
        q("'මගෙ කුමරියෙ ඔබ පානා සෙනේ' වැනි ගීතවලින් දක්නට ලැබෙන නූර්ති සංගීතයේ සුවිශේෂී අංගය කුමක්ද?", "රාගධාරී අලංකාර සහ තාන යෙදීම", "සංකීර්ණ බටහිර කෝඩ්ස් යෙදීම", "තාල රහිතව පාඨ කියවීම", "හම්ප් කැරොල් තනු භාවිතය", "නූර්ති ගී බොහෝ විට යමන්, භූපාලි, භෛරවී, කාෆි වැනි රාගවල අලංකාරවලින් පෝෂණය විය."),
        q("නාඩගම් නළුවා වේදිකාවට එන විට අත්වැල් ගායකයන් හා මද්දලකරු එක්ව පවත්වන පෙළගැස්ම කෙසේ හඳුන්වයිද?", "සබේ විදීම හා පිවිසුම් නැටුම", "තිරය වසා දැමීම", "අවසන් තිර සංගීතය", "විවේක කාල වාදනය", "නළුවා වේදිකාවේ දෙවරක් තුන්වරක් ගමන් කරමින් තාලයට අනුව සබයට එළඹෙයි."),
        q("සොකරි නාටකය රඟදක්වන ප්‍රධාන භූමිය හෙවත් රංග පීඨය කුමක්ද?", "වී පාගන කමත", "කොළඹ රඟහල", "මහනුවර රජමාලිගාව", "වෙරළ තීරය", "ගොයම් කපා පාගා ගත් පසු ගමේ කමත සොකරි රඟදැක්වීමේ රංග මණ්ඩපය වේ."),
        q("සොකරි නාටකයේ කතා නායකයා වන ගුරුහාමිගේ සහායකයා කවුද?", "පරයා", "වැදි රජු", "සෙල්ලම් ලමයා", "පොතේගුරු", "සොකරි නාටකයේ හාස්‍ය හා සංවාද රසය මතු කරන සහායක චරිතය පරයාය."),
        q("සොකරි නාටකයේ ගායනා කරනු ලබන සොකරි කවිවල ප්‍රධාන ලක්ෂණය කුමක්ද?", "සරල ජන ගී නාද රටාවෙන් යුක්ත වීම", "සංකීර්ණ ඛ්‍යාල් ශෛලියෙන් ගැයීම", "බටහිර සොප්‍රානෝ හඬින් ගැයීම", "දෙමළ සංගීත තාල පමණක් ගැනීම", "සොකරි කවි ගැමි ජනතාවට ඉතා සමීප සරල හා ලයාන්විත නාද රටා ගනී."),
        q("කෝලම් නාට්‍යයේ එන 'නාග කන්‍යා' හෝ 'මරක්කල' වැනි කෝලම් ඉදිරිපත් කිරීමට පෙර ගැයෙනුයේ කුමක්ද?", "අදාළ චරිතය හඳුන්වන විස්තර කවි", "ඉංග්‍රීසි ගීතිකා", "සංස්කෘත නාට්‍ය පද්‍ය", "චිත්‍රපට තේමා ගී", "සෑම වෙස්මුහුණු චරිතයක්ම වේදිකාවට එන විට කාරියකරවන රාළ විසින් එම චරිතයේ කවි ගයයි."),
        q("රටේ පැවති අධිරාජ්‍යවාදී පාලනය විවේචනය කිරීමට හා දේශප්‍රේමය ඇති කිරීමට නාට්‍ය ගීත යොදාගත්තේ කවුද?", "ජෝන් ද සිල්වා", "පිලිප්පු සිංඤෝ", "අමීර් ඛුස්රෝ", "විෂ්ණු දිගම්බර පලුස්කර්", "ජෝන් ද සිල්වා ශ්‍රී වික්‍රම හා දුටුගැමුණු වැනි නූර්තිවලින් ජාතික හැඟීම් උද්දීපනය කළේය."),
        q("'සිරිසඟබෝ' නාට්‍යයේ රජු තම හිස දන් දෙන ශෝකජනක අවස්ථාව සඳහා යොදාගත් සංගීත රසය කුමක්ද?", "කරුණ රසය", "හාස්‍ය රසය", "ශෘංගාර රසය", "රෞද්‍ර රසය", "දුක්මුසු ශෝකාකූල අවස්ථාවලදී කරුණ රසය ජනනය කරන රාග තනු භාවිත කෙරේ."),
        q("නාඩගම් ගීතවල පවතින 'සින්දුව' යන කොටස හඳුන්වන විශේෂ ලක්ෂණය කුමක්ද?", "නැවත නැවත ගැයෙන තාලානුකූල තනු කොටස", "තාල රහිත ආලාප කොටස", "දෙබස් කියවන කොටස", "නාට්‍යයේ අවසාන නිවේදනය", "නාඩගමේ පල්ලවි, අනුපල්ලවි වැනි කොටස් සහිතව තාලයට ගැයෙන ගීත සින්දු වේ."),
        q("දයානන්ද ගුණවර්ධනයන්ගේ 'බක්මහ අකුණු' වේදිකා නාට්‍යයේ සංගීතය නිර්මාණය කළේ කවුද?", "සෝමදාස ඇල්විටිගල", "විශ්වනාත් ලෞජි", "ෂෙල්ටන් ප්‍රේමරත්න", "ඩබ්ලිව්. ඩී. අමරදේව", "බක්මහ අකුණු නාට්‍යයේ මිහිරි ගීත තනු සෝමදාස ඇල්විටිගලයන්ගේ නිර්මාණයන්ය."),
        q("'මංගල දිනේ' හෝ 'මලින් මලේ රේණු උරා' වැනි ගීත ඇතුළත් වේදිකා නාට්‍යය කුමක්ද?", "බක්මහ අකුණු", "සිංහබාහු", "මනමේ", "කැලණි පාලම", "ලොකු මිනිසුන්ගේ කතා හා ගැමි රසය මුසු බක්මහ අකුණු නාට්‍යයේ මෙම ගීත ඇතුළත් වේ."),
        q("ශ්‍රී ලංකාවේ ප්‍රථම ගීත නාට්‍ය මෙන්ම ජන ගී පදනම් කරගත් 'කැලේ මල්' වැනි නිර්මාණ බිහිවූයේ කවුරුන් අතින්ද?", "ඩබ්ලිව්. බී. මකුලොළුව", "ජෝන් ද සිල්වා", "පිලිප්පු සිංඤෝ", "සරත් දසනායක", "දේශීය ජන ගී පර්යේෂණයෙන් ලද ආභාසය මකුලොළුවන්ගේ නිර්මාණවල කැපී පෙනුණි."),
        q("ගුවන්විදුලි නාට්‍ය සංගීතයේදී 'ශබ්ද ප්‍රයෝග' හා සංගීත ඛණ්ඩ යොදාගන්නේ කුමන අරමුණක් සඳහාද?", "දෘශ්‍ය රූප නොමැතිව සිද්ධි ශ්‍රාවක මනසේ මැවීමට", "වැඩසටහන් කාලය දීර්ඝ කිරීමට පමණක්", "කථිකයාගේ හඬ මැඩපැවැත්වීමට", "වාදකයන්ගේ දක්ෂතා පෙන්වීමට පමණක්", "රූප රාමු නැති ගුවන්විදුලි නාට්‍යවල පරිසරය හා මනෝභාවය ශබ්දයෙන් මැවිය යුතුය."),
        q("'පුංචි බබා මම පුංචි බබා' වැනි ළමා නාට්‍ය ගීත සිංහල වේදිකාවට ගෙන ආ ප්‍රවීණයා කවුද?", "සෝමලතා සුබසිංහ", "ජෝන් ද සිල්වා", "පිලිප්පු සිංඤෝ", "සී. දොන් බස්තියන්", "විකෘති, තොප්පි වෙළෙන්දා, පුංචි අපට දැන් තේරෙයි වැනි ළමා නාට්‍ය සෝමලතා සුබසිංහ නිපදවූවාය."),
        q("සෝමලතා සුබසිංහගේ 'තොප්පි වෙළෙන්දා' ළමා නාට්‍යයේ සංගීතය සකස් කළේ කුමන සංගීත රටාව අනුවද?", "දරුවන්ට හුරු රිද්මයානුකූල සරල සංගීතය", "බරපතළ ද්‍රැපද් ශාස්ත්‍රීය රාග", "වේගවත් හෙවි මෙටල් රොක්", "නිහඬ භාවනා සංගීතය", "ළමුන්ගේ චලන හා ගායන හැකියාවන්ට ගැළපෙන සරල ජන රිද්ම මෙහි යොදාගැණිනි."),
        q("නාට්‍යයක චරිතයක් වේදිකාවෙන් පිටව යන විට වාදනය කරන කෙටි සංගීත කොටස හඳුන්වන්නේ කුමන නමකින්ද?", "නික්මුම් වාදනය", "ප්‍රවේශ අලාපය", "මංගල අෂ්ටකය", "සර්ගම් තානය", "චරිතයේ මනෝභාවය තවදුරටත් රඳවමින් වේදිකාවෙන් නික්ම යෑමට සංගීත කොටස වාදනය වේ."),
        q("සංස්කෘත නාට්‍ය සම්ප්‍රදායේ ආරම්භක පූජා රංගනය හඳුන්වනු ලබන්නේ කුමන නමින්ද?", "පූර්ව රංගය", "භරත වාක්‍යය", "විෂ්කම්භකය", "ප්‍රස්තාවනාව", "සංස්කෘත මෙන්ම නාඩගම් වැනි නාට්‍යවලදී මුලින්ම දේව වන්දනාව සහිත පූර්ව රංගය පවත්වයි."),
        q("නාට්‍යයක් අවසානයේදී සියල්ලන්ටම සෙත් පතා ගායනා කරන සමාප්ති පද්‍යය කුමක්ද?", "භරත වාක්‍යය (අවසන් ආශිර්වාද ගීය)", "ඉන්නිස ගීතය", "අණබෙර ගීතය", "පිවිසුම් තාල පදය", "සම්භාව්‍ය නාට්‍ය අවසානයේ සෙත් පැතීමේ භරත වාක්‍යය ගායනා කිරීමේ සිරිත පවතී."),
        q("'විකෘති' වේදිකා නාට්‍යයේ සංගීතය නිර්මාණය කළ ප්‍රවීණ සංගීත අධ්‍යක්ෂවරයා කවුද?", "එම්. ආර්. චූලසිංහ", "විශ්වනාත් ලෞජි", "ආනන්ද සමරකෝන්", "මොහොමඩ් ගවුස්", "සෝමලතා සුබසිංහගේ විකෘති නාට්‍යයේ ආකර්ෂණීය සංගීතය එම්. ආර්. චූලසිංහ නිර්මාණය කළේය."),
        q("සිංහල නාට්‍යයේ සම්භාව්‍ය යුගය ලෙස සැලකෙන 1956න් පසු යුගයේදී 'පසන්' හා 'යාග' කවි නාද මාලා යොදාගත්තේ කවුද?", "පේරාදෙණිය නාට්‍ය පරපුර", "ටවර් හෝල් නූර්ති පරපුර", "ග්‍රැමෆෝන් තැටි පරපුර", "පාර්සි නාට්‍ය පරපුර", "සරච්චන්ද්‍ර ප්‍රමුඛ පේරාදෙණිය නාට්‍ය පරපුර දේශීය ශබ්ද මූලාශ්‍ර ගවේෂණය කළේය."),
        q("'වැස්ස වලාහක දෙවියනේ' හෝ ජනශ්‍රැතික නාද මාලා භාවිතය නූතන නාට්‍ය සංගීතයට ලබා දුන්නේ කුමක්ද?", "දේශීය අනන්‍යතාවක් සහ ජන හදගැස්ම", "විදේශීය හුරුවක් පමණක්", "කාර්මික ශබ්ද ප්‍රයෝග", "අත්‍යවශ්‍ය නොවන දීර්ඝත්වය", "දේශීය සංස්කෘතික උරුමය ඇසුරින් අපේම නාට්‍ය සංගීතයක් ගොඩනැගීමට එය මග පෑදීය."),
        q("ග්‍රැමෆෝන් තැටියක පටිගත කළ හැකිව තිබූ සාමාන්‍ය ගීතයක කාල සීමාව එදා කොපමණ වීද?", "විනාඩි 3ක් පමණ", "විනාඩි 30ක් පමණ", "තත්පර 10ක් පමණ", "පැය 1ක් පමණ", "78 RPM ග්‍රැමෆෝන් තැටියක එක් පැත්තක ධාරිතාව විනාඩි 3කට සීමා වූ නිසා කෙටි සරල ගී බිහිවිය."),
        q("නූර්ති යුගයේ සිට ග්‍රැමෆෝන් යුගයට ගීත පැමිණීමේදී සිදුවූ ප්‍රධාන වෙනස්කම කුමක්ද?", "දීර්ඝ වේදිකා ගී කෙටි ස්වාධීන ගී බවට පත්වීම", "වාද්‍ය භාණ්ඩ සම්පූර්ණයෙන් ඉවත් කිරීම", "සිංහල භාෂාව වෙනුවට දෙමළ භාවිතය", "රාග සංගීතය තහනම් කිරීම", "විනාඩි 3 තැටි සීමාව නිසා කෙටි, ආකර්ෂණීය ස්ථායි අන්තරා සහිත සරල ගීත ආකෘතිය බිහිවිය."),
        q("'ශ්‍රී ලංකා මාතා' ජාතික ගීයේ නිර්මාතෘ ආනන්ද සමරකෝන් ගීත කලාවේ මුලින්ම විප්ලවයක් කළේ කවර මාධ්‍යයෙන්ද?", "ග්‍රැමෆෝන් සරල ගී මාධ්‍යයෙන්", "නාඩගම් මාධ්‍යයෙන්", "ටෙලිනාට්‍ය මාධ්‍යයෙන්", "සොකරි මාධ්‍යයෙන්", "1940 දශකයේ ග්‍රැමෆෝන් ගී තැටි හරහා ආනන්ද සමරකෝන් නව සරල ගී රීතිය හඳුන්වා දුන්නේය."),
        q("ආනන්ද සමරකෝන්ගේ සරල ගී නිර්මාණ තුළ බහුලව දැකිය හැකි වූ ප්‍රධාන තේමාවන් මොනවාද?", "ගැමි පරිසරය, ස්වභාවධර්මය හා දේශාභිමානය", "රාජ සභා යුද ජයග්‍රහණ පමණක්", "විදේශීය නගර ජීවිතය", "සංස්කෘත ව්‍යාකරණ නීති", "පොඩි මල් එතනෝ, විලේ මලක් වැනි ගීතවලින් හෙළ ගැමි සෞන්දර්යය ගැයුණි."),
        q("සිංහල ගීත කලාවේ 'හෙළ හවුල' හා බැඳුණු සුනිල් ශාන්තයන් ගීත නිර්මාණය කළේ කුමන මාධ්‍යය කේන්ද්‍ර කරගෙනද?", "ගුවන්විදුලි සරල ගී මාධ්‍යය", "නාඩගම් රඟමඬල", "ටවර් හෝල් නූර්ති වේදිකාව", "බටහිර ඔපෙරා වේදිකාව", "ලංකා ගුවන්විදුලි සේවය හරහා සුනිල් ශාන්තයන් ස්වතන්ත්‍ර හෙළ ගීත ප්‍රචලිත කළේය."),
        q("නාඩගම් නාට්‍යයේ 'වැල්ලවාය' හෝ 'මහසම්මත' වැනි කතා ගයන අතරතුර ප්‍රේක්ෂකයාට විවේකයක් ලබා දෙන්නේ කවුද?", "කෝනංගියා හා සෙල්ලම් ලමයා", "වැදි රජු", "පොතේගුරු", "සබාපති", "නාඩගම් කතාව අතරතුර විකට ජවනිකා මගින් කෝනංගියා ප්‍රේක්ෂකයාට විනෝදාස්වාදය දෙයි."),
        q("සිංහල චිත්‍රපට සංගීතයේ හින්දි හා දෙමළ තනු අනුකරණයෙන් මිදී දේශීය තනු නිර්මාණයට මග පෑදූ චිත්‍රපටය කුමක්ද?", "රේඛාව (1956)", "කඩවුණු පොරොන්දුව (1947)", "සංදේශය (1960)", "වැලිකතර (1971)", "ලෙස්ටර් ජේම්ස් පීරිස්ගේ රේඛාව චිත්‍රපටයට සුනිල් ශාන්තයන් ස්වතන්ත්‍ර සංගීතය නිර්මාණය කළේය."),
        q("රේඛාව චිත්‍රපටයේ 'ඕලු නෙළුම් නෙරිය රඟාලා' වැනි ස්වතන්ත්‍ර ගී තනු නිර්මාණය කළේ කවුද?", "සුනිල් ශාන්ත", "ආර්. මුත්තුසාමි", "විශ්වනාත් ලෞජි", "ආනන්ද සමරකෝන්", "සුනිල් ශාන්තයන්ගේ තනු සහ මර්සලීන් ජයකොඩි පියතුමාගේ පද රචනය රේඛාවේ ඇතුළත් විය."),
        q("සංදේශය චිත්‍රපටයේ 'පෘතුගීසි කාරයා' හා 'රැජිණ මමයි' වැනි විශිෂ්ට තනු නිර්මාණය කළේ කවුද?", "ආර්. මුත්තුසාමි", "ප්‍රේමසිරි කේමදාස", "සුනිල් ශාන්ත", "ඩබ්ලිව්. ඩී. අමරදේව", "ආර්. මුත්තුසාමි මහතාගේ සංගීතයෙන් සංදේශය චිත්‍රපටයේ ජනප්‍රිය ගීත බිහිවිය."),
        q("නාට්‍ය සංගීතයේදී 'තේමා වාදනය' (Theme Music) මගින් සිදු කෙරෙන ප්‍රධාන කාර්යය කුමක්ද?", "නාට්‍යයේ මූලික හරය හා හැඟීම සංකේතවත් කිරීම", "වාද්‍ය භාණ්ඩවල සුසර පරීක්ෂා කිරීම", "ප්‍රේක්ෂකයන්ට පිටව යන ලෙස දැන්වීම", "දෙබස් අමතක වූ විට කාලය ගැනීම", "තේමා සංගීතය නාට්‍යයේ ප්‍රධාන තේමාව හා රසය ප්‍රේක්ෂක මනසට කාවද්දයි."),
        q("සිංහල වේදිකා නාට්‍ය ඉතිහාසයේ 'ප්‍රොසීනියම් වේදිකාව' ප්‍රථම වරට යොදාගැණුනේ කුමන යුගයේද?", "නූර්ති යුගයේ", "නාඩගම් යුගයේ", "සොකරි යුගයේ", "ගැමි තොවිල් යුගයේ", "ඉදිරිපස තිර රෙදි සහිත පින්තූර රාමු වේදිකාව (Proscenium) නූර්ති හරහා මෙරටට ආවේය."),
        q("සම්ප්‍රදායික නාඩගම් පොත්වල ගීතයක් කුමන තාලයකට ගැයිය යුතුද යන්න දැක්වූයේ කෙසේද?", "සින්දුව හා තාල නාමය සටහන් කිරීමෙන්", "බටහිර ස්ටාෆ් ස්වර ප්‍රස්තාරයෙන්", "භාත්ඛණ්ඩේ ස්වර ප්‍රස්තාරයෙන්", "ඩිජිටල් ශ්‍රව්‍ය ගොනුවකින්", "පැරණි නාඩගම් පොත්වල අඩි තාල, මුල් තාල හෝ චපු තාල ආදි තාල නාම දක්වා තිබුණි."),
        q("ශ්‍රී ලංකාවේ 'ටීටර්' (Teater) නාට්‍ය සම්ප්‍රදාය හා නූර්ති කලාව අතර ඇති සම්බන්ධය කුමක්ද?", "ගීත හා තිර රෙදි සහිත නූර්තිවලට සමාන වීම", "කෝලම් වෙස්මුහුණු පමණක් පැළඳීම", "වචන නොමැති නැටුමක් පමණක් වීම", "කමතේ පමණක් රඟදැක්වීම", "දෙමළ හා ක්‍රිස්තියානි ප්‍රදේශවල පාර්සි ආභාසයෙන් බිහිවූ නූර්තිවලට සමාන වේදිකා නාට්‍ය ටීටර් වේ."),
        q("මනමේ නාට්‍යයේ 'හස්ති පොල්ලැල්ලේ' හෝ 'වැද්දාගේ කවි' වැනි තැන්වලදී බෙර වාදනයෙන් මවන්නේ කුමක්ද?", "චරිතයේ ජවය සහ නාට්‍යමය උද්වේගය", "පූර්ණ නිහැඬියාව", "බටහිර සංගීත ස්වර සංයෝගය", "ළමා නැළවිලි ගී හඬ", "තීරණාත්මක අවස්ථාවලදී මද්දල හඬ නාට්‍යමය ගැටුම හා උද්වේගය තීව්‍ර කරයි."),
        q("'සාන්තුවරයාණනි' වැනි ගීත ඇතුළත් නූතන ගීත නාටක නිර්මාණයේදී බහුලව භාවිත වන සංගීත ක්‍රමය කුමක්ද?", "බටහිර හා පෙරදිග සංගීත සංකලනය", "තාලම්පට පමණක් වාදනය කිරීම", "හුදු මුඛ වාදනය පමණක් යෙදීම", "එක් ස්වරයක් පමණක් ගැයීම", "නූතන ගීත නාටකවල ප්‍රකාශන ශක්තිය වැඩි කිරීමට පෙර-අපර දෙදිගම වාද්‍ය භාණ්ඩ මුසු කරගනී."),
        q("සිංහල සංගීත නාට්‍ය කලාව තුළ 'සංගීත අධ්‍යක්ෂවරයාගේ' ප්‍රධාන වගකීම කුමක්ද?", "කතා පුවතට හා චරිතවලට උචිත නාද මාලා සැපයීම", "වේදිකා තිර රෙදි මැසීම", "ප්‍රවේශපත්‍ර අලෙවි කිරීම", "නළුවන්ගේ ඇඳුම් මැදීම", "නාට්‍ය පෙළෙහි රසභාව තේරුම් ගෙන ඊට අනුකූල ගායන හා වාදන නිර්මාණය කිරීම ඔහුගේ කාර්යයයි."),
        q("'දෙවියන් විසින් ලොවට දුන් අනර්ඝ දායාදය' ආදි ලෙස සංගීතයේ අගය වර්ණනා කරන නූර්ති ගීත ලියවුණේ කවර යුගයේද?", "ටවර් හෝල් නූර්ති යුගයේ", "නූතන සිනමා යුගයේ", "රූකඩ නාට්‍ය යුගයේ", "වෙසක් නාට්‍ය යුගයේ", "ටවර් හෝල් නූර්ති යුගයේ සමාජ සාරධර්ම හා කලාව වර්ණනා කරන ගීත බහුල විය."),
        q("'කිඳුරු කුමාරි' හෝ 'සඳකිඳුරු' ජන නාටකයේ ගායනා සඳහා සාම්ප්‍රදායිකව යොදාගන්නා වාද්‍ය භාණ්ඩය කුමක්ද?", "උඩැක්කිය හෝ ගැටබෙරය", "සිතාරය හා සන්තූරය", "සැක්සෆෝනය හා ගිටාරය", "පියානෝව හා චෙලෝව", "ගැමි සඳකිඳුරු නැටුමේදී උඩැක්කිය හෝ දවුල, ගැටබෙරය භාවිත කෙරේ."),
        q("දකුණු ඉන්දීය ආභාසය ලත් නාඩගම් ගීත ගායනයේදී ගායකයන් භාවිත කළ හඬ පිහිටුවීමේ ස්වභාවය කුමක්ද?", "විවෘත උස් හඬින් (Open Voice) ගැයීම", "ඉතා මෘදු කොඳුරන හඬින් ගැයීම", "මයික්‍රොෆෝනයට ළංව ගැයීම", "නාසික හඬින් පමණක් ගැයීම", "එළිමහන් කරළියේ සියලු දෙනාට ඇසෙන පරිදි උච්ච විවෘත හඬින් ගැයීම සිරිත විය."),
        q("නාඩගම් කලාවේදී 'තානා' ගායනා කිරීමෙන් අදහස් කරන්නේ කුමක්ද?", "චරිතයකට පෙර කියන රිද්මයානුකූල වචන පෙළක්", "නාට්‍යය අවසන් කිරීමේ සීනුව", "වේදිකාවේ පහන් නිවා දැමීම", "රසිකයන්ගෙන් මුදල් එකතු කිරීම", "සමහර චරිත පිවිසුම්වලදී තාලයට ගැළපෙන පරිදි නාද ගත වචන පද උච්චාරණය කෙරේ."),
        q("'මනමේ' නාට්‍යයේ ශාස්ත්‍රීය අගය රඳා පවතින්නේ කුමන සාධක දෙකේ සුසංයෝගයෙන්ද?", "ජාතක කතා පුවත හා නාඩගම් නාට්‍ය ශෛලිය", "බටහිර නවකතාව හා රොක් සංගීතය", "විකට කතා හා බයිලා සංගීතය", "සංස්කෘත ව්‍යාකරණ හා ඔපෙරාව", "චුල්ල ධනුද්ධර ජාතක කතාව දේශීය නාඩගම් රීතිය සමඟ ඒකාබද්ධ වීම මනමේ හි අගය වැඩි කළේය."),
        q("'සිංහබාහු' නාට්‍යයේ 'පුතු සෙනේ' ප්‍රකාශ වන සිංහයාගේ ගීත කවර චරිත ස්වභාවයක් මතු කරයිද?", "අසරණ වූ පීතෘ සෙනෙහස හා වේදනාව", "කෲර හාස්‍යය හා උපහාසය", "දේශපාලන උපායශීලී බව", "යුද ජයග්‍රහණයේ උද්දාමය", "සිංහයා තම පුතුන් හා බිරිඳ හැරයෑම නිසා විඳින ශෝකය ගීතවලින් මැනවින් ප්‍රකාශ වේ."),
        q("පාර්සි නාට්‍ය සමාගම්වල ආභාසයෙන් සිංහල නූර්ති වේදිකාවට එක්වූ ප්‍රසාංගික අංගයක් වන්නේ කුමක්ද?", "සමූහ ගායනා හා ආකර්ෂණීය වේදිකා පසුබිම්", "සඳළුතල නැති ගොම මැටි බිම", "ගොයම් කවි පමණක් ගැයීම", "බෙර වාදනය සම්පූර්ණයෙන් ඉවත් කිරීම", "පාර්සි නාට්‍ය ආකෘතිය නිසා සිතුවම් කළ පසුබිම් තිර හා නාට්‍ය ගීත නූර්තියට ලැබුණි."),
        q("ගුවන්විදුලි නාට්‍ය මෙන්ම වේදිකා නාට්‍ය රැසකට සංගීතය සැපයූ 'ප්‍රේමසිරි කේමදාස' සංගීතවේදියා ප්‍රකට කවර නවෝත්පාදනයකටද?", "පෙරදිග රාග හා බටහිර සිම්ෆනි වාදනය සංයෝජනය කිරීම", "හුදෙක් ගැමි රබන් පද පමණක් ගැසීම", "ඉන්දීය චිත්‍රපට තනු කොපි කිරීම", "මද්දලය පමණක් යොදාගැනීම", "කේමදාස මාස්ටර් පෙරදිග හා බටහිර වාද්‍ය භාණ්ඩ සහ න්‍යායන් නිර්මාණශීලීව මුසු කළේය."),
        q("'නාඩගම් රාත්‍රී කිහිපයක් පුරා රඟදැක්වීම' පැරණි සමාජයේ සිදුවූයේ කෙසේද?", "ගම්වාසීන්ගේ රාත්‍රී විනෝදාස්වාදය උදෙසා", "උදෑසන පාසල් ළමුන් උදෙසා පමණක්", "කෙටි විනාඩි 10 වැඩසටහනක් ලෙස", "වෙළඳ ප්‍රචාරණ දැන්වීම් ලෙස", "දීර්ඝ රජ කතා රාත්‍රියේ සිට එළිවන තුරු දින කිහිපයක් ගැමි පිරිස් ඉදිරියේ රඟදැක්විණි."),
        q("'ජන සංගීතය වේදිකා නාට්‍යයට ගෙන ආ යුතුය' යන මතය ප්‍රායෝගිකව තහවුරු කළ නාට්‍යයක් වන්නේ කුමක්ද?", "නරිබෑණා", "හැම්ලට්", "ඊඩිපස්", "රොලීනා", "දයානන්ද ගුණවර්ධනයන්ගේ නරිබෑණා නාට්‍යය සිංහල ජන කවි හා ජන නාදයෙන් පෝෂණය විය."),
        q("'වළලු වළලු මල් වළලු' වැනි ගීත ඇතුළත් ජනප්‍රිය නාට්‍යය නිර්මාණය කළේ කවුද?", "ලුසියන් බුලත්සිංහල (තාරාවෝ ඉගිලෙති)", "ජෝන් ද සිල්වා (සිරිසඟබෝ)", "පිලිප්පු සිංඤෝ (ඇහැලේපොළ)", "සී. දොන් බස්තියන් (රොලීනා)", "තාරාවෝ ඉගිලෙති නාට්‍යයේ ආකර්ෂණීය ගීත අතර මෙවැනි ගීත දක්නට ලැබේ."),
        q("නාඩගම් වේදිකාවේ පොතේගුරු ගයන පළමු පද්‍ය කොටස හා පද්‍ය පෙළ හැඳින්වෙන්නේ කෙසේද?", "වර්ණනා කවි හා ඉන්නිස", "ඛ්‍යාල් හා තරානා", "ධ්‍රැපද් හා ධමාර්", "කීර්තනා හා කෘති", "නාඩගම් ආරම්භයේ පොතේගුරු දෙවිවරුන් හා කතා සාරාංශය කවියෙන් හා ඉන්නිසෙන් කියයි."),
        q("'හුණුවටයේ කතාව' නාට්‍යයේ සෑම ප්‍රධාන සිදුවීමක්ම පාහේ සම්බන්ධ කරමින් ගීත ගයන්නේ කවුද?", "පොතේගුරු / ගායක පිරිස", "අධිකරණ විනිසුරු අස්ඩක්", "සෙබළ සයිමන්", "ගෘෂාගේ සොහොයුරා", "කථිකයා හා ගායක පිරිස කතාවේ දර්ශන සම්බන්ධ කරමින් අර්ථවත් ගීත ගායනා කරති."),
        q("නූර්ති ගීත කලාව පසුකාලීන සිංහල සරල ගීත කලාව කෙරෙහි ඇති කළ ධනාත්මක බලපෑම කුමක්ද?", "උත්තර භාරතීය රාග හා තාල මෙරට ජනගත වීම", "සිංහල භාෂාව ගීතවලින් ඉවත් වීම", "තබ්ලාව භාවිතය අහෝසි වීම", "ගැමි ජන ගී සම්පූර්ණයෙන් අමතක වීම", "නූර්ති ගී නිසා රාගධාරී ශෛලිය හා හාමෝනියම් තබ්ලා වාදනය මෙරට ස්ථාපිත විය."),
        q("ශ්‍රී ලංකාවේ 'චරිතාංග නාට්‍ය ගීත' ගායනයේදී ගායකයෙකු සතුවිය යුතු විශේෂ කුසලතාව කුමක්ද?", "හඬෙහි නාට්‍යමය භාව ප්‍රකාශන හැකියාව", "ශබ්දය අඩු කොඳුරන හඬක් තිබීම", "වේගයෙන් වචන කියවීම පමණක්", "තාලය ගැන සැලකිලිමත් නොවීම", "නාට්‍ය චරිතයක කෝපය, දුක හෝ සතුට කටහඬින් නිරූපණය කිරීමේ හැකියාව අත්‍යවශ්‍ය වේ."),
        q("වේදිකා නාට්‍යයකදී සංගීතය මගින් කාලය හා ස්ථානය වෙනස් වීම පෙන්වීම හඳුන්වන්නේ කෙසේද?", "අන්තරාල හෝ සංක්‍රාන්ති සංගීතය", "අවසන් ආශිර්වාද ගීය", "පූර්ව රංග පූජා ගීය", "ලයාන්විත නැළවිලි ගීය", "දර්ශනයකින් තවත් දර්ශනයකට මාරුවීමේදී ප්‍රේක්ෂක අවධානය රඳවන සංක්‍රාන්ති සංගීතය වාදනය වේ."),
        q("'අන්දරේ' හෝ 'මහදැනමුත්තා' වැනි හාස්‍යජනක නාට්‍ය නිර්මාණවලදී බහුලව මතුවන රසය කුමක්ද?", "හාස්‍ය රසය", "බීභත්ස රසය", "භයානක රසය", "ශාන්ත රසය", "උපහාසාත්මක සිදුවීම් හා සැහැල්ලු නාද රටා හරහා හාස්‍ය රසය ඉස්මතු කෙරේ."),
        q("සිංහල ග්‍රැමෆෝන් ගීත යුගයේ හින්දි තනු අනුකරණය කිරීමට විරුද්ධව නැගී සිටි ගීත සම්ප්‍රදාය කුමක්ද?", "ස්වතන්ත්‍ර සිංහල සරල ගී සම්ප්‍රදාය", "පාර්සි නූර්ති සම්ප්‍රදාය", "ටීටර් සම්ප්‍රදාය", "පෘතුගීසි කපිරිඤ්ඤා සම්ප්‍රදාය", "ආනන්ද සමරකෝන් හා සුනිල් ශාන්ත අනුකාරක තනුවලින් මිදී ස්වතන්ත්‍ර තනු නිර්මාණය කළහ."),
        q("පැරණි කෝලම් නාට්‍යයේ එන 'ජසයා සහ ලෙන්චිනා' නව වේදිකාවට ගැළපෙන පරිදි ප්‍රතිනිර්මාණය කළේ කවුද?", "සිරිසේන විමලවීර / ගුණසේන ගලප්පත්ති", "පිලිප්පු සිංඤෝ", "විශ්වනාත් ලෞජි", "ජෝන් ද සිල්වා", "සාම්ප්‍රදායික කෝලම් පෙළ ආශ්‍රයෙන් නූතන වේදිකා නාට්‍ය බිහිවිය."),
        q("'වන්නම්' ආකෘතිය හා තාල රටා භාවිත කරමින් නාට්‍ය ගී නිර්මාණය කළ අවස්ථාවක් ලෙස ගත හැක්කේ කුමක්ද?", "මහාචාර්ය සරච්චන්ද්‍රගේ සමහර ශෛලිගත නාට්‍ය ගී", "බටහිර ඉංග්‍රීසි පල්ලියේ ගීතිකා", "පාර්සි චිත්‍රපට ගීත", "තමිල් තෙරුක්කූත්තු සින්දු", "දේශීය වන්නම් නාද මාලා හා ඡන්දස් ශෛලිගත නාට්‍ය කලාව පෝෂණය කිරීමට යොදාගැනිණි."),
        q("ශ්‍රී ලංකාවේ ප්‍රථම වරට වේදිකා නාට්‍ය සංගීතය සඳහා බටහිර වාද්‍ය වෘන්ද ලක්ෂණ විශාල වශයෙන් ගෙන ආ නාට්‍ය සම්ප්‍රදාය කුමක්ද?", "නූතන සිංහල ඔපෙරා හා කේමදාසගේ නාට්‍ය", "පැරණි සොකරි නාටක", "ගැමි කෝලම් නැටුම්", "දකුණේ රූකඩ නාට්‍ය", "ප්‍රේමසිරි කේමදාස වැනි සංගීතඥයෝ බටහිර සංධ්වනි හා ගායක වෘන්ද ලක්ෂණ වේදිකාවට ගෙන ආහ."),
        q("නාඩගමක චරිතයකට වේදිකාවේ තමා හඳුන්වා දීම සඳහා ගැයෙන ගීත විශේෂය හඳුන්වන්නේ කුමන නමකින්ද?", "ප්‍රවේශ සින්දුව හෙවත් දොරට වැඩීමේ ගීතය", "අවසන් මංගල ගීතය", "කෝනංගි විහිළු ගීතය", "සමාප්ති කවි පෙළ", "ප්‍රධාන චරිත වේදිකාවට එළඹෙන විට තම තරාතිරම හා අරමුණ කියන සින්දුවක් ගයයි."),
        q("'පාර්සි' නාට්‍ය කලාවේ මව්බිම ලෙස සැලකෙන්නේ කුමන ඉන්දියානු නගරයද?", "බොම්බාය (මුම්බායි)", "මදුරාසිය (චෙන්නායි)", "කල්කටාව (කොල්කතා)", "දිල්ලිය", "ඉන්දියාවේ බොම්බාය කේන්ද්‍ර කරගත් පාර්සි නාට්‍ය කණ්ඩායම් ලංකාවට පැමිණ නූර්තියට මග පෑදීය."),
        q("ජෝන් ද සිල්වාගේ නූර්ති නාට්‍ය නැරඹීමට පැමිණි ප්‍රේක්ෂකයාට ප්‍රධාන වශයෙන් ලැබුණු සමාජ පණිවිඩය කුමක්ද?", "බෞද්ධ සාරධර්ම, අමද්‍යප ප්‍රතිපත්ති හා ජාතිකත්වය", "විදේශීය පාලනය වර්ණනා කිරීම", "නූතන තාක්ෂණික දැනුම", "වෙළඳ ව්‍යාපාර දියුණුව", "අධිරාජ්‍යවාදයට එරෙහිව සිංහල බෞද්ධ සංස්කෘතිය නගාසිටුවීම ජෝන් ද සිල්වාගේ අරමුණ විය."),
        q("ග්‍රැමෆෝන් තැටි නිපදවීමට පෙර ගීත ජනතාව අතර ව්‍යාප්ත වූ ප්‍රධානතම ක්‍රමය කුමක්ද?", "සජීවී නාට්‍ය ශාලා සහ කටවහර", "අන්තර්ජාලය හා සමාජ මාධ්‍ය", "රූපවාහිනී නාලිකා", "සංයුක්ත තැටි (CD)", "පටිගත කිරීමේ තාක්ෂණය එන්නට පෙර මිනිසුන් නූර්ති හා නාඩගම් ශාලාවලින් ගීත ඉගෙන ගත්හ."),
        q("'සුභ සහ යස' නාට්‍යයේ සංගීතය හා ගීත සඳහා දායක වූ ප්‍රකට කලාකරුවා කවුද?", "සයිමන් නවගත්තේගම සහ සංගීත පිරිස", "පිලිප්පු සිංඤෝ", "විශ්වනාත් ලෞජි", "සී. දොන් බස්තියන්", "ජනශ්‍රැති කතා පුවතක් ඇසුරින් සැකසුණු සුභ සහ යස නූතන වේදිකා නාට්‍ය අතර ප්‍රමුඛ වේ."),
        q("නාට්‍යයක චරිතයකට තමාගේ අභ්‍යන්තර සිතිවිලි ගීතයෙන් ප්‍රකාශ කිරීමට ඇති අවස්ථාව හඳුන්වන්නේ කෙසේද?", "ස්වගත ගායනය", "සමූහ ගායනය", "යුග ගායනය", "පසුබිම් නිවේදනය", "වේදිකාවේ තනිව සිටිමින් චරිතයේ සිතුවිලි ගායනයෙන් පැවසීම ස්වගත ගායනයකි."),
        q("'වේදිකා නාට්‍යයක තිර රෙදි විවෘත කිරීමට පෙර වාදනය කරන සංගීතය' කවර නමකින් හැඳින්වේද?", "පෙර සංගීතය (Overture / නාන්දි වාදනය)", "පසු සංගීතය", "විවේක සංගීතය", "සමාප්ති සංගීතය", "නාට්‍යයේ මනෝභාවයට ප්‍රේක්ෂකයා සූදානම් කිරීම සඳහා පෙර වාදනය ඉදිරිපත් කෙරේ."),
        q("නූතන සිංහල සංගීත නාට්‍ය සඳහා නවීන තාල රටා හා ජන නාද එක්කරන අතරම පැරණි උරුමය රැකගැනීම කුමක් සඳහා වැදගත් වේද?", "ශ්‍රී ලාංකේය සංගීත අනන්‍යතාව පවත්වා ගැනීමට", "සංගීත භාණ්ඩ අඩු කිරීමට", "ගායකයන්ගේ සංඛ්‍යාව සීමා කිරීමට", "නාට්‍ය කාලය කෙටි කිරීමට", "දේශීය හරය රැකගනිමින් නව ලොවට ගැළපෙන සංගීත නිර්මාණ බිහිකිරීම කලාවේ ප්‍රගමනයට හේතු වේ."),
        q("නාඩගම් වේදිකාවේ මූලික වශයෙන් බෙර වාදනය සඳහා යොදාගත් සාම්ප්‍රදායික අවනද්ධ වාද්‍ය භාණ්ඩය කුමක්ද?", "මද්දලය", "තබ්ලාව", "පඛාවජය", "බොංගෝ බෙරය", "නාඩගම් ගීතවලට දකුණු ඉන්දීය ආභාසය ඇති මද්දල බෙරය ප්‍රධාන තාල භාණ්ඩය විය."),
        q("සිංහල නූර්ති වේදිකාවේ සර්පිනාව (හාමෝනියම්) සමඟ ප්‍රධාන තාල වාද්‍ය භාණ්ඩය ලෙස භාවිත වූයේ කුමක්ද?", "තබ්ලාව", "මද්දලය", "උඩැක්කිය", "තම්මැට්ටම", "උත්තර භාරතීය රාගධාරී තනු අනුව ගිය නූර්ති ගීත සඳහා තබ්ලාව හා හාමෝනියමය යොදාගැනිණි."),
        q("'පාර්සි' නාට්‍ය සම්ප්‍රදාය අනුගමනය කරමින් සී. දොන් බස්තියන් නිෂ්පාදනය කළ මුල්ම නූර්ති නාට්‍යය ලෙස සැලකෙන්නේ කුමක්ද?", "රොලීනා", "මනමේ", "සිංහබාහු", "නරිබෑණා", "1877 පමණ වේදිකාගත කළ 'රොලීනා' සිංහල නූර්ති යුගයේ ආරම්භක සන්ධිස්ථානයකි."),
        q("මහාචාර්ය සරච්චන්ද්‍රයන්ගේ 'සිංහබාහු' නාට්‍යයේ සංගීත නිර්මාණය සඳහා නාද මාලා සැපයූ විශිෂ්ට සංගීතඥයා කවුද?", "එච්. එච්. බණ්ඩාර", "ආනන්ද සමරකෝන්", "සුනිල් ශාන්ත", "ජෝන් ද සිල්වා", "සිංහබාහු නාට්‍යයේ සාම්ප්‍රදායික නාඩගම් නාද මාලා එච්. එච්. බණ්ඩාරගේ මද්දල වාදනයෙන් ඔප්නැංවිණි."),
        q("දයානන්ද ගුණවර්ධනයන්ගේ 'මධුර ජවනිකා' හා 'නරිබෑණා' වැනි නාට්‍යවල සංගීතය සඳහා පදනම් කරගත් ප්‍රධාන මූලාශ්‍රය කුමක්ද?", "සිංහල ජන ගී හා ගැමි නාද රටා", "බටහිර ජෑස් සංගීතය", "පාර්සි චිත්‍රපට ගීත", "කර්ණාටක කීර්තනා පමණක්", "දයානන්ද ගුණවර්ධන දේශීය ජන කවි හා සිංදු වේදිකා නාට්‍ය සංගීතයට මනාව මුසු කළේය."),
        q("හෙන්රි ජයසේනයන්ගේ 'හුණුවටයේ කතාව' නාට්‍යයේ ප්‍රශංසනීය සංගීත අධ්‍යක්ෂණය සිදු කළේ කවුද?", "ෂෙල්ටන් ප්‍රේමරත්න", "ප්‍රේමසිරි කේමදාස", "ඩබ්ලිව්. ඩී. අමරදේව", "විශ්වනාත් ලෞජි", "ෂෙල්ටන් ප්‍රේමරත්න හුණුවටයේ කතාව සඳහා අමරණීය ගී තනු නිර්මාණය කළේය."),
        q("නාඩගමක ආරම්භයේදී චරිත වේදිකාවට කැඳවමින් කතාව විස්තර කරන ප්‍රධාන පුද්ගලයා හඳුන්වන්නේ කෙසේද?", "පොතේගුරු", "විදූෂකයා", "මද්දල වාදකයා", "නූර්ති අධ්‍යක්ෂක", "පොතේගුරු ගායනයෙන් හා විස්තරයෙන් නාඩගමේ දර්ශන එකිනෙක සම්බන්ධ කරයි."),
        q("නූර්ති නාට්‍ය ගීත බොහොමයක දක්නට ලැබුණු වේගවත් භාරතීය නාට්‍ය ගීත ආර හඳුන්වන ලද්දේ කුමන නමින්ද?", "ටීටර් හෝ නූර්ති රාග සින්දු", "සැහැල්ලු ජන කවි", "පිරිත් සජ්ඣායනා", "පැල් කවි විරිදු", "පාර්සි නාට්‍ය ආභාසයෙන් උපන් නූර්ති ගී උත්තර භාරතීය රාග තනු මත නිර්මාණය විය.")
    )
}
